/**
 * Plugin to show ByteBlock data in various formats.
 */
public class ByteViewerPlugin : AbstractByteViewerPlugin<ProgramByteViewerComponentProvider> {

	public ByteViewerPlugin(PluginTool tool) : base(tool)
    {
	}

	/* @Override */
	protected ProgramByteViewerComponentProvider createProvider(bool isConnected) {
		return new ProgramByteViewerComponentProvider(tool, this, isConnected);
	}

	/* @Override */
	public void processEvent(PluginEvent @event) {
		if (@event is ProgramClosedPluginEvent ev) {
			Program program = ev.getProgram();
			programClosed(program);
		}
		else if (@event is ProgramActivatedPluginEvent ev) {
			currentProgram = ev.getActiveProgram();
			currentLocation = null;
		}
		else if (@event is ProgramLocationPluginEvent ev) {
			currentLocation = ev.getLocation();
		}

		connectedProvider.doHandleEvent(@event);
	}

	void programClosed(Program closedProgram) {
		Iterator<ProgramByteViewerComponentProvider> iterator = disconnectedProviders.iterator();
		while (_iterator.hasNext()) {
			ProgramByteViewerComponentProvider provider = _iterator.next();
			if (provider.getProgram() == closedProgram) {
				_iterator.remove();
				removeProvider(provider);
			}
		}
	}

	/* @Override */
	public void highlightChanged(ByteViewerComponentProvider provider, ProgramSelection highlight) {
		if (provider == connectedProvider) {
			tool.firePluginEvent(new ProgramHighlightPluginEvent(getName(), highlight,
				connectedProvider.getProgram()));
		}
	}
}
